const rawBody = $input.item.json.body;
let data = {};
try {
  data = typeof rawBody === 'string' ? JSON.parse(rawBody) : (rawBody || {});
} catch (e) {
  throw new Error('Invalid JSON payload');
}

const meta = data.meta || {};
const contact = data.contact || {};
const diag = data.diagnostic || null;

let rawPhone = contact.telefono || '';
let cleanPhone = rawPhone.replace(/\D/g, '');
if (cleanPhone.startsWith('0')) cleanPhone = cleanPhone.slice(1);
if (cleanPhone.startsWith('54') && !cleanPhone.startsWith('549')) {
  cleanPhone = '549' + cleanPhone.slice(2);
} else if (!cleanPhone.startsWith('549') && cleanPhone.length >= 10) {
  cleanPhone = '549' + cleanPhone;
}
const waPhone = cleanPhone ? '+' + cleanPhone : '';
const isCritico = diag && diag.level === 'critico';

let tgText = `<b>${isCritico ? '🔴 ALERTA LEAD CRÍTICO' : '📥 NUEVO LEAD'} - SEGURIDAD PRL</b>\n\n`;
tgText += `<b>Lead ID:</b> <code>${meta.lead_id || 'N/A'}</code>\n`;
tgText += `<b>Origen:</b> ${meta.source || 'N/A'} (${meta.event || ''})\n\n`;
tgText += `👤 <b>Nombre:</b> ${contact.nombre || '-'}\n`;
tgText += `🏢 <b>Empresa:</b> ${contact.empresa || '-'}\n`;
tgText += `💼 <b>Cargo:</b> ${contact.cargo || '-'}\n`;
tgText += `📍 <b>Localidad:</b> ${contact.localidad || '-'}\n`;
tgText += `🏭 <b>Rubro:</b> ${contact.rubro || '-'}\n`;
tgText += `📱 <b>WhatsApp:</b> ${contact.telefono || '-'} ${waPhone ? `(<a href="https://wa.me/${waPhone.replace('+','')}">Abrir Chat</a>)` : ''}\n`;
tgText += `✉️ <b>Email:</b> ${contact.email || '-'}\n\n`;

if (data.message) {
  tgText += `💬 <b>Mensaje:</b> ${data.message}\n\n`;
}

if (diag) {
  tgText += `📊 <b>DIAGNÓSTICO REGISTRADO</b>\n`;
  tgText += `• <b>Nivel:</b> ${diag.level_label || diag.level} (${diag.score}/100)\n`;
  tgText += `• <b>Servicios Sugeridos:</b> ${(diag.priority_services || []).join(', ')}\n`;
}

return [{
  json: {
    lead_id: meta.lead_id,
    submitted_at: meta.submitted_at,
    event: meta.event,
    source: meta.source,
    nombre: contact.nombre,
    empresa: contact.empresa,
    cargo: contact.cargo,
    email: contact.email,
    telefono: contact.telefono,
    wa_phone: waPhone,
    rubro: contact.rubro,
    localidad: contact.localidad,
    mensaje: data.message || '',
    diag_score: diag ? diag.score : '',
    diag_level: diag ? diag.level : '',
    diag_services: diag ? (diag.priority_services || []).join('; ') : '',
    is_critico: isCritico,
    telegram_text: tgText,
    utm_source: (meta.utm && meta.utm.source) || '',
    utm_campaign: (meta.utm && meta.utm.campaign) || ''
  }
}];
